import sys

def solve(n, k):
    if k > n * n // 2:
        return -1

    matrix = [[0] * n for _ in range(n)]

    # Place ones on the main diagonal first
    for i in range(min(k, n)):
        matrix[i][i] = 1
        k -= 1

    # Place remaining ones symmetrically
    for i in range(n):
        for j in range(i + 1, n):
            if k == 0:
                break
            matrix[i][j] = 1
            matrix[j][i] = 1
            k -= 2

    return matrix

def print_matrix(matrix):
    for row in matrix:
        print(" ".join(map(str, row)))

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    k = int(data[1])

    result = solve(n, k)

    if result == -1:
        print(-1)
    else:
        print_matrix(result)

if __name__ == "__main__":
    main()
